<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
class CanteenStudentController extends Controller{
 private function sid(Request $r){abort_unless($r->user()->student_id,403);return $r->user()->student_id;}
 public function index(Request $r){$sid=$this->sid($r);$today=date('Y-m-d');$assignment=DB::table('student_meal_assignments as a')->join('meal_categories as c','c.id','=','a.meal_category_id')->where('a.student_id',$sid)->where('a.valid_from','<=',$today)->where(function($q)use($today){$q->whereNull('a.valid_to')->orWhere('a.valid_to','>=',$today);})->select('a.*','c.name as category_name')->orderByDesc('a.valid_from')->first();$pass=DB::table('student_meal_passes')->where(['student_id'=>$sid,'status'=>'active'])->first();if(!$pass&&$assignment){$id=DB::table('student_meal_passes')->insertGetId(['student_id'=>$sid,'token'=>Str::random(56),'status'=>'active','issued_at'=>now(),'issued_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);$pass=DB::table('student_meal_passes')->find($id);}$menus=DB::table('meal_menus')->whereBetween('menu_date',[$today,date('Y-m-d',strtotime('+7 days'))])->where('active',1)->orderBy('menu_date')->get();$orders=DB::table('meal_preorders')->where('student_id',$sid)->where('meal_date','>=',$today)->pluck('status','meal_menu_id');$issues=DB::table('meal_issues')->where('student_id',$sid)->orderByDesc('issued_at')->limit(20)->get();return view('canteen.student',compact('assignment','pass','menus','orders','issues'));}
 public function preorder(Request $r,$menu){$sid=$this->sid($r);$m=DB::table('meal_menus')->find($menu);abort_if(!$m||$m->menu_date<date('Y-m-d'),404);DB::table('meal_preorders')->updateOrInsert(['student_id'=>$sid,'meal_menu_id'=>$menu],['meal_date'=>$m->menu_date,'status'=>'ordered','updated_at'=>now(),'created_at'=>now()]);return back()->with('success','Заказ сохранён.');}
 public function cancel(Request $r,$menu){$sid=$this->sid($r);DB::table('meal_preorders')->where(['student_id'=>$sid,'meal_menu_id'=>$menu])->where('meal_date','>',date('Y-m-d'))->update(['status'=>'cancelled','updated_at'=>now()]);return back()->with('success','Заказ отменён.');}
}